#!/usr/bin/env python3# -*- coding: latin-1 -*-"""Move/rename subfolder HTML into root and normalize asset paths.For each first-level subdirectory under this script's directory:  - Find index.html|index.htm (case-insensitive).  - Move it to root as <subdir>.html (overwriting if exists).  - Rewrite inside the moved HTML:      * CSS references:          - <link ... href="...something.css">  -> href="<basename>.css"          - @import "foo/bar.css";              -> "bar.css"          - @import url("../baz.css");          -> "baz.css"      * Image references:          - <img src="anything/any/path/name.ext"> -> src="img/name.ext"          - background="anything/name.ext"         -> background="img/name.ext"Notes:- Encoding: latin-1- Only first-level subfolders are scanned (non-recursive)."""import osimport reimport shutil# ------------------------------- Utilities ----------------------------------def case_insensitive_find(dirpath, candidates):    """Return the first matching file path (case-insensitive) if it exists."""    try:        names = os.listdir(dirpath)    except FileNotFoundError:        return None    lower = {n.lower(): n for n in names}    for cand in candidates:        real = lower.get(cand.lower())        if real:            p = os.path.join(dirpath, real)            if os.path.isfile(p):                return p    return Nonedef ensure_dir(path: str) -> None:    os.makedirs(path, exist_ok=True)def read_text(path: str) -> str:    with open(path, "r", encoding="latin-1", errors="replace") as f:        return f.read()def write_text(path: str, s: str) -> None:    with open(path, "w", encoding="latin-1", errors="strict") as f:        f.write(s)def path_basename(p: str) -> str:    """Return the last component (file name) after any slashes/backslashes."""    # Normalize slashes and split    p = p.replace("\\", "/")    return p.split("/")[-1]# --------------------------- HTML Rewriters ---------------------------------def _rewrite_css_links(html: str) -> str:    """    Normalize <link ... href="...*.css"> to just the basename (remove ../ and dirs).    Also fixes @import rules inside <style> blocks.    """    # (1) <link ... href="...file.css"...>    def link_repl(m):        before = m.group(1)      # '<link ... href=' plus the opening quote        quote = m.group(2)        fullval = m.group(3)     # the current href value (no quotes)        basename = path_basename(fullval)        return f'{before}{quote}{basename}{quote}'    # capture: (<link...href=)(['"])(value)\2    link_pat = re.compile(r'(<\s*link\b[^>]*?\bhref\s*=\s*)([\'"])([^\'"]+)\2',                          flags=re.IGNORECASE)    html = link_pat.sub(link_repl, html)    # (2) @import inside <style> or anywhere in HTML (simple normalization)    #    @import "path/to/file.css";    #    @import url("path/to/file.css");    def import_repl_plain(m):        quote = m.group(1)        val = m.group(2)        basename = path_basename(val)        return f'@import {quote}{basename}{quote};'    import_plain_pat = re.compile(r'@import\s+([\'"])([^\'"]+)\1\s*;',                                  flags=re.IGNORECASE)    html = import_plain_pat.sub(import_repl_plain, html)    def import_repl_url(m):        quote = m.group(1) or ''        val = m.group(2)        basename = path_basename(val)        if quote:            return f'@import url({quote}{basename}{quote});'        else:            return f'@import url({basename});'    import_url_pat = re.compile(r'@import\s+url\(\s*([\'"]?)([^)\'"]+)\1\s*\)\s*;',                                flags=re.IGNORECASE)    html = import_url_pat.sub(import_repl_url, html)    return htmldef _rewrite_img_src(html: str) -> str:    """    Normalize <img src="..."> paths so they become img/<filename>.    Also fix legacy background="...".    """    # (1) <img ... src="...">    def img_repl(m):        before = m.group(1)        quote = m.group(2)        val = m.group(3)        base = path_basename(val)        newval = f'img/{base}'        return f'{before}{quote}{newval}{quote}'    img_pat = re.compile(r'(<\s*img\b[^>]*?\bsrc\s*=\s*)([\'"])([^\'"]+)\2',                         flags=re.IGNORECASE)    html = img_pat.sub(img_repl, html)    # (2) legacy background="...":    def bg_repl(m):        before = m.group(1)        quote = m.group(2)        val = m.group(3)        base = path_basename(val)        newval = f'img/{base}'        return f'{before}{quote}{newval}{quote}'    bg_pat = re.compile(r'(\bbackground\s*=\s*)([\'"])([^\'"]+)\2',                        flags=re.IGNORECASE)    html = bg_pat.sub(bg_repl, html)    return htmldef rewrite_paths_for_root(html_text: str) -> str:    """    Apply all normalizations for CSS and images.    """    s = html_text    s = _rewrite_css_links(s)    s = _rewrite_img_src(s)    return s# ------------------------------- Main Task ----------------------------------def move_and_fix_htmls():    root = os.path.abspath(os.path.dirname(__file__))    for name in os.listdir(root):        subdir = os.path.join(root, name)        if not os.path.isdir(subdir):            continue        html_path = case_insensitive_find(subdir, ["index.html", "index.htm"])        if not html_path:            continue        new_name = f"{name}.html"        dst_path = os.path.join(root, new_name)        # Read, rewrite, then move (rewrite first so any relative calc is straightforward)        original = read_text(html_path)        fixed = rewrite_paths_for_root(original)        # Ensure destination path is free        if os.path.exists(dst_path):            os.remove(dst_path)        # Write the fixed HTML directly to the destination, then remove source        write_text(dst_path, fixed)        try:            os.remove(html_path)        except OSError:            # If the source can't be removed for some reason, ignore silently            pass        print(f"Moved + fixed: {html_path} -> {dst_path}")if __name__ == "__main__":    move_and_fix_htmls()